import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";

const SEARCH_URL = "https://api.tavily.com/search";
const EXTRACT_URL = "https://api.tavily.com/extract";

function apiKey(): string {
  const key = process.env.TAVILY_API_KEY;
  if (!key) {
    throw new Error("TAVILY_API_KEY is not set. Set it in the environment and run /reload.");
  }
  return key;
}

async function tavilyRequest(url: string, body: Record<string, unknown>, signal?: AbortSignal) {
  const response = await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ api_key: apiKey(), ...body }),
    signal,
  });
  const text = await response.text();
  if (!response.ok) {
    throw new Error(`Tavily API error (${response.status}): ${text.slice(0, 500)}`);
  }
  return JSON.parse(text) as Record<string, unknown>;
}

export default function (pi: ExtensionAPI) {
  pi.registerTool({
    name: "web_search",
    label: "Web Search",
    description: "Search the web with Tavily. Use this for current information and provide source URLs in the answer.",
    parameters: Type.Object({
      query: Type.String({ description: "The web search query" }),
      search_depth: Type.Optional(Type.Union([
        Type.Literal("basic"),
        Type.Literal("advanced"),
      ], { description: "Search depth; advanced is slower and more thorough" })),
      topic: Type.Optional(Type.Union([
        Type.Literal("general"),
        Type.Literal("news"),
      ], { description: "Search topic" })),
      max_results: Type.Optional(Type.Integer({ minimum: 1, maximum: 10, description: "Maximum results to return" })),
      days: Type.Optional(Type.Integer({ minimum: 1, description: "For news searches, only return results from this many recent days" })),
      domains: Type.Optional(Type.Array(Type.String(), { description: "Only search these domains" })),
      exclude_domains: Type.Optional(Type.Array(Type.String(), { description: "Exclude these domains" })),
      include_raw_content: Type.Optional(Type.Boolean({ description: "Include extracted page text when available" })),
    }),
    async execute(_toolCallId, params, signal) {
      const result = await tavilyRequest(SEARCH_URL, {
        query: params.query,
        search_depth: params.search_depth ?? "basic",
        topic: params.topic ?? "general",
        max_results: params.max_results ?? 5,
        ...(params.days === undefined ? {} : { days: params.days }),
        ...(params.domains?.length ? { include_domains: params.domains } : {}),
        ...(params.exclude_domains?.length ? { exclude_domains: params.exclude_domains } : {}),
        ...(params.include_raw_content === undefined ? {} : { include_raw_content: params.include_raw_content }),
      }, signal);
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        details: { provider: "tavily", query: params.query },
      };
    },
  });

  pi.registerTool({
    name: "web_fetch",
    label: "Fetch Web Page",
    description: "Extract readable content from one or more web pages with Tavily. Use after web_search to inspect sources.",
    parameters: Type.Object({
      urls: Type.Array(Type.String({ description: "A complete http(s) URL" }), { minItems: 1, maxItems: 5 }),
    }),
    async execute(_toolCallId, params, signal) {
      const result = await tavilyRequest(EXTRACT_URL, { urls: params.urls }, signal);
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
        details: { provider: "tavily", urls: params.urls },
      };
    },
  });
}
